sqlGroup.select:
select
	a.*
from sys_func a
left join sys_menu b on a.menuid=b.id


		and a.id = #{id}


		and a.name = #{name}


		and a.code = #{code}


		and a.actionType = #{actionType}


		and a.action = #{action}


		and a.targetAction = #{targetAction}


		and (a.action = #{actionQ} or a.targetAction = #{actionQ})


		and a.display = #{display}


		and a.menuid = #{menuid}


		and b.url = #{url}
